import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@300;400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type FitnessAppPromoProps = Record<string, any>;

const FitnessAppPromo: React.FC<FitnessAppPromoProps> = ({
  backgroundColor = "#F9F9FB",
  transparentBackground = false,
  primaryColor = "#FF8C69",
  durationInSeconds = 10,
  stepsCount = 17450,
  orbitRadius = 400,
  orbitSpeed = 1,
  orbitImage1 = "",
  orbitImage2 = "",
  orbitImage3 = "",
}) => {
  useFontLoader(["Montserrat"]);
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Color Handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Drivers
  const entrance = spring({
    frame,
    fps,
    config: { damping: 200 },
  });

  const rotation = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0, 360 * orbitSpeed]
  );

  const stepCounter = Math.floor(
    interpolate(frame, [0, fps * 2], [0, stepsCount], {
      extrapolateRight: "clamp",
    })
  );

  // Formatting the number
  const formattedSteps = stepCounter.toLocaleString("en-US");

  // Fallback images (colored gradients) if none provided
  const placeholders = [
    "linear-gradient(135deg, #a8edea 0%, #fed6e3 100%)",
    "linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)",
    "linear-gradient(135deg, #e0c3fc 0%, #8ec5fc 100%)",
  ];

  // Group individual image props into an array for processing
  const images = [orbitImage1, orbitImage2, orbitImage3];

  const orbitItems = [0, 1, 2].map((i) => {
    const angleOffset = i * 120; // 3 items spaced evenly
    const currentAngle = (rotation + angleOffset) * (Math.PI / 180);
    const cx = width / 2 + orbitRadius * Math.cos(currentAngle);
    const cy = height / 2 + orbitRadius * Math.sin(currentAngle);

    const imgSource = images[i] || placeholders[i];
    const isImage = images[i] && images[i].length > 0;

    return { cx, cy, imgSource, isImage, id: i };
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Montserrat",
        color: "#1a1a1a",
      }}
    >
      {/* --- Background Orbits --- */}
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        {[1.2, 0.8].map((scale, i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              width: orbitRadius * 2 * scale,
              height: orbitRadius * 2 * scale,
              borderRadius: "50%",
              border: "1px solid rgba(0,0,0,0.05)",
              transform: `scale(${entrance})`,
            }}
          />
        ))}
      </AbsoluteFill>

      {/* --- Main Center Hub --- */}
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <div
          style={{
            width: 450,
            height: 450,
            backgroundColor: "white",
            borderRadius: "50%",
            boxShadow: `0 30px 80px -20px ${primaryColor}66`, // Soft glow
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${entrance})`,
            position: "relative",
            zIndex: 10,
          }}
        >
          {/* Inner Content */}
          <div
            style={{
              opacity: interpolate(frame, [10, 30], [0, 1]),
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
            }}
          >
            <span
              style={{
                fontSize: 18,
                fontWeight: 600,
                color: "#888",
                letterSpacing: "0.5px",
                display: "block",
                marginBottom: 10,
              }}
            >
              Steps
            </span>
            <div
              style={{
                fontSize: 80,
                fontWeight: 700,
                lineHeight: 1,
                marginBottom: 20,
                color: "#000",
                fontVariantNumeric: "tabular-nums",
              }}
            >
              {formattedSteps}
            </div>
          </div>
        </div>
      </AbsoluteFill>

      {/* --- Orbiting Items --- */}
      {orbitItems.map((item) => (
        <div
          key={item.id}
          style={{
            position: "absolute",
            left: item.cx,
            top: item.cy,
            width: 180,
            height: 180,
            marginLeft: -90, // Center the anchor
            marginTop: -90,
            borderRadius: "50%",
            overflow: "hidden",
            boxShadow: "0 10px 20px rgba(0,0,0,0.1)",
            opacity: entrance,
            transform: `scale(${entrance})`,
            zIndex: 5,
          }}
        >
          {item.isImage ? (
            <img
              src={item.imgSource}
              alt=""
              style={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
              }}
            />
          ) : (
            <div
              style={{
                width: "100%",
                height: "100%",
                background: item.imgSource,
              }}
            />
          )}
        </div>
      ))}
    </AbsoluteFill>
  );
};

export default FitnessAppPromo;